'use strict';

// MODULES //

var isnan = require( '@stdlib/math-base-assert-is-nan' );
var floor = require( '@stdlib/math-base-special-floor' );
var gindexOfGreaterThanEqual = require( '@stdlib/blas-ext-base-gindex-of-greater-than-equal' ).ndarray;


// MAIN //

/**
* Returns the index of the first element in a sorted strided array which is greater than or equal to a specified search element.
*
* @private
* @param {PositiveInteger} N - number of indexed elements
* @param {*} searchElement - search element
* @param {Object} x - sorted input array object
* @param {Collection} x.data - input array data
* @param {Array<Function>} x.accessors - array element accessors
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {integer} index
*
* @example
* var toAccessorArray = require( '@stdlib/array-base-to-accessor-array' );
* var arraylike2object = require( '@stdlib/array-base-arraylike2object' );
*
* var x = [ 1.0, 2.0, 2.0, 3.0 ];
*
* var idx = gindexOfGreaterThanEqualSorted( x.length, 2.0, arraylike2object( toAccessorArray( x ) ), 1, 0 );
* // returns 1
*/
function gindexOfGreaterThanEqualSorted( N, searchElement, x, strideX, offsetX ) {
	var xbuf;
	var get;
	var idx;
	var mid;
	var lo;
	var hi;
	var v1;
	var v2;
	var v;

	// Cache reference to array data:
	xbuf = x.data;

	// Cache a reference to the element accessors:
	get = x.accessors[ 0 ];

	v1 = get( xbuf, offsetX );
	v2 = get( xbuf, offsetX + ( ( N - 1 ) * strideX ) );

	// If either the first or last indexed element is NaN, we cannot determine the sort order, so fall back to a linear search...
	if ( isnan( v1 ) || isnan( v2 ) ) {
		return gindexOfGreaterThanEqual( N, searchElement, xbuf, strideX, offsetX );
	}
	// Descending order: elements which are greater than or equal to the search element form a prefix, so only the first indexed element needs to be checked...
	if ( v1 >= v2 ) {
		if ( searchElement <= v1 ) {
			return 0;
		}
		return -1;
	}
	// Ascending order: perform a binary search for the first element which is greater than or equal to the search element...
	lo = 0;
	hi = N;
	while ( lo < hi ) {
		mid = lo + floor( ( hi - lo ) / 2 );
		v = get( xbuf, offsetX + ( mid * strideX ) );

		// If we encounter a NaN, fall back to a linear search over the remaining candidate elements...
		if ( isnan( v ) ) {
			idx = gindexOfGreaterThanEqual( N-lo, searchElement, xbuf, strideX, offsetX + ( lo * strideX ) );
			return ( idx < 0 ) ? idx : idx + lo;
		}
		if ( searchElement <= v ) {
			hi = mid;
		} else {
			lo = mid + 1;
		}
	}
	if ( lo === N ) {
		return -1;
	}
	return lo;
}


// EXPORTS //

module.exports = gindexOfGreaterThanEqualSorted;
